import hashlib, marshal, sys, os, hmac as _hm

def _ad():
    try:
        with open("/proc/self/status", "r") as f:
            for l in f:
                if l.startswith("TracerPid"):
                    if int(l.split()[1]) != 0: os._exit(9)
                    break
    except: pass

_ad()

_s = bytes.fromhex("05dfc87836df855da8f04566a062fb4f")
_n = bytes.fromhex("9829b2a7fbd0aedde89af64e431e580e")
_h = bytes.fromhex("f493cc75918720bbffb8da3308085af650a53f227d612398109404d12addcc81")
_d = bytes.fromhex("")

_m0 = bytes.fromhex("5da460bcf75f1675")
_p0 = bytes.fromhex("6d13385422e6333e")
_m1 = bytes.fromhex("1350ae168b980c8a")
_p1 = bytes.fromhex("b5239bd0d53b5aeb")
_m2 = bytes.fromhex("5f24b809d246317c")
_p2 = bytes.fromhex("0b6d5e5a5b157e75")
_m3 = bytes.fromhex("dd78b1c877362829")
_p3 = bytes.fromhex("f3f4b06b7d7a00f6")

_k = bytes(a^b for a,b in zip(_p0,_m0)) + bytes(a^b for a,b in zip(_p1,_m1)) + bytes(a^b for a,b in zip(_p2,_m2)) + bytes(a^b for a,b in zip(_p3,_m3))

_dk = hashlib.pbkdf2_hmac("sha256", _k, _s, 5000, dklen=32)

_hk = hashlib.sha256(_dk).digest()
_hv = _hm.new(_hk, _d, hashlib.sha256).digest()
if _hv != _h: os._exit(7)

def _dec(data, dk, nonce):
    r = bytearray(); c = 0; o = 0
    while o < len(data):
        ks = hashlib.sha256(dk + nonce + c.to_bytes(8, "big")).digest()
        ch = data[o:o+32]
        for i in range(len(ch)): r.append(ch[i] ^ ks[i])
        o += 32; c += 1
    return bytes(r)

_m = _dec(_d, _dk, _n)
exec(marshal.loads(_m))